-- ================================================================\n-- ADD ACCOUNT ARCHIVE FUNCTIONS AND AUTOMATIC DELETION\n-- ================================================================\n\n-- 1. Add archive column to profiles\nALTER TABLE public.profiles\n  ADD COLUMN IF NOT EXISTS archived_at timestamptz;\n\n-- 2. Archive function: moves suspended account to archive\nCREATE OR REPLACE FUNCTION public.tours_admin_archive_account(p_user_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_suspended boolean;\n  v_reason text;\n  v_suspended_at timestamptz;\nBEGIN\n  IF get_my_role() IS DISTINCT FROM 'admin' THEN\n    RAISE EXCEPTION 'Only admins can archive accounts.' USING ERRCODE = '42501';\n  END IF;\n  IF p_user_id = auth.uid() THEN\n    RAISE EXCEPTION 'You cannot archive your own account.' USING ERRCODE = '22023';\n  END IF;\n  SELECT is_suspended, suspended_reason, suspended_at INTO v_suspended, v_reason, v_suspended_at FROM profiles WHERE id = p_user_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Account not found.' USING ERRCODE = '22023';\n  END IF;\n  IF NOT v_suspended THEN\n    RAISE EXCEPTION 'Account must be suspended before archiving.' USING ERRCODE = '22023';\n  END IF;\n  \n  -- Mark as archived (keep suspended status, add archived_at)\n  UPDATE profiles\n     SET archived_at = now()\n   WHERE id = p_user_id;\n   \n  INSERT INTO tours_admin_audit_log (admin_id, action, entity_type, entity_id, old_value, new_value, notes)\n  VALUES (auth.uid(), 'archive_user', 'user', p_user_id,\n          to_jsonb(false)::text, to_jsonb(true)::text, v_reason);\nEND;\n$$;\nREVOKE ALL ON FUNCTION public.tours_admin_archive_account(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.tours_admin_archive_account(uuid) TO authenticated;\n\n-- 3. Restore function: removes archive status and restores suspension if needed\nCREATE OR REPLACE FUNCTION public.tours_admin_restore_account(p_user_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_archived timestamptz;\n  v_suspended boolean;\nBEGIN\n  IF get_my_role() IS DISTINCT FROM 'admin' THEN\n    RAISE EXCEPTION 'Only admins can restore accounts.' USING ERRCODE = '42501';\n  END IF;\n  SELECT archived_at, is_suspended INTO v_archived, v_suspended FROM profiles WHERE id = p_user_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Account not found.' USING ERRCODE = '22023';\n  END IF;\n  IF v_archived IS NULL THEN\n    RAISE EXCEPTION 'Account is not archived.' USING ERRCODE = '22023';\n  END IF;\n  \n  -- Remove archive status and restore suspension (set is_suspended = false)\n  UPDATE profiles\n     SET archived_at = NULL,\n         is_suspended = false,\n         suspended_at = NULL,\n         suspended_reason = NULL,\n         suspended_until = NULL\n   WHERE id = p_user_id;\n   \n  -- Also lift Auth ban (if the server action handles it, we also trigger it)\n  -- Note: The server action already handles Auth ban lifting in setAccountSuspended\n  \n  INSERT INTO tours_admin_audit_log (admin_id, action, entity_type, entity_id, old_value, new_value, notes)\n  VALUES (auth.uid(), 'unarchive_user', 'user', p_user_id,\n          to_jsonb(true)::text, to_jsonb(false)::text, 'Account restored from archive');\nEND;\n$$;\nREVOKE ALL ON FUNCTION public.tours_admin_restore_account(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.tours_admin_restore_account(uuid) TO authenticated;\n\n-- 4. Permanent delete function: deletes the account from profiles and auth\nCREATE OR REPLACE FUNCTION public.tours_admin_delete_account(p_user_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_archived timestamptz;\nBEGIN\n  IF get_my_role() IS DISTINCT FROM 'admin' THEN\n    RAISE EXCEPTION 'Only admins can delete accounts.' USING ERRCODE = '42501';\n  END IF;\n  IF p_user_id = auth.uid() THEN\n    RAISE EXCEPTION 'You cannot delete your own account.' USING ERRCODE = '22023';\n  END IF;\n  SELECT archived_at INTO v_archived FROM profiles WHERE id = p_user_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Account not found.' USING ERRCODE = '22023';\n  END IF;\n  IF v_archived IS NULL THEN\n    RAISE EXCEPTION 'Account must be archived before permanent deletion.' USING ERRCODE = '22023';\n  END IF;\n  \n  -- Delete from profiles (cascades to related tables depending on schema)\n  DELETE FROM profiles WHERE id = p_user_id;\n  \n  -- Delete from auth.users (requires service role, handled by Supabase Admin client in server action)\n  -- The server action will call createSupabaseAdminClient().auth.admin.deleteUserById(p_user_id)\n  \n  INSERT INTO tours_admin_audit_log (admin_id, action, entity_type, entity_id, old_value, new_value, notes)\n  VALUES (auth.uid(), 'delete_user', 'user', p_user_id,\n          to_jsonb(true)::text, NULL, 'Account permanently deleted from archive');\nEND;\n$$;\nREVOKE ALL ON FUNCTION public.tours_admin_delete_account(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.tours_admin_delete_account(uuid) TO authenticated;\n\n-- 5. Automatic deletion function: deletes archived accounts older than 90 days\nCREATE OR REPLACE FUNCTION public.tours_admin_auto_delete_archive()\nRETURNS int\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_deleted int;\nBEGIN\n  IF get_my_role() IS DISTINCT FROM 'admin' THEN RETURN 0; END IF;\n  \n  -- Delete profiles that are archived and suspended for > 90 days\n  DELETE FROM profiles\n   WHERE archived_at IS NOT NULL\n     AND archived_at <= now() - interval '90 days'\n     AND is_suspended\n   RETURNING id INTO STRICT v_deleted;\n   \n  -- Note: Server action will also delete from auth.users\n  \n  RETURN COALESCE(v_deleted, 0);\nEND;\n$$;\nREVOKE ALL ON FUNCTION public.tours_admin_auto_delete_archive() FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.tours_admin_auto_delete_archive() TO authenticated;\n\n-- 6. List archived accounts function\nCREATE OR REPLACE FUNCTION public.tours_admin_list_archived_accounts(p_query text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)\nRETURNS jsonb\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = public, auth\nAS $$\nDECLARE\n  v_q text := NULLIF(btrim(COALESCE(p_query, '')), '');\n  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);\nBEGIN\n  IF get_my_role() IS DISTINCT FROM 'admin' THEN\n    RAISE EXCEPTION 'Only admins can manage archived accounts.' USING ERRCODE = '42501';\n  END IF;\n  RETURN (\n    WITH matched AS (\n      SELECT pr.id, pr.full_name, pr.role, pr.created_at, pr.is_suspended, pr.suspended_at, pr.suspended_reason,\n             pr.archived_at,\n             u.email::text AS email, u.last_sign_in_at,\n             EXISTS (SELECT 1 FROM tours_operators o WHERE o.profile_id = pr.id) AS has_operator,\n             EXISTS (SELECT 1 FROM tours_guides g WHERE g.profile_id = pr.id) AS has_guide\n        FROM profiles pr\n        LEFT JOIN auth.users u ON u.id = pr.id\n       WHERE pr.archived_at IS NOT NULL\n         AND (v_q IS NULL OR pr.full_name ILIKE '%' || v_q || '%' OR u.email ILIKE '%' || v_q || '%')\n    )\n    SELECT jsonb_build_object(\n      'total', (SELECT count(*) FROM matched)::int,\n      'accounts', COALESCE((SELECT jsonb_agg(row_to_json(m) ORDER BY m.created_at DESC) FROM (\n        SELECT * FROM matched ORDER BY created_at DESC LIMIT v_limit OFFSET GREATEST(COALESCE(p_offset, 0), 0)\n      ) m), '[]'::jsonb)\n    )\n  );\nEND;\n$$;\nREVOKE ALL ON FUNCTION public.tours_admin_list_archived_accounts(text, integer, integer) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.tours_admin_list_archived_accounts(text, integer, integer) TO authenticated;\n\n-- ================================================================\n-- MIGRATION COMPLETE\n-- ================================================================\n